"""HTML5 canvas — declarative, retained-mode 2D drawing.

A :class:`Canvas` is a fixed-size drawing surface filled by a list of draw *ops*
(:class:`Rect`, :class:`Circle`, :class:`Line`, :class:`Path`,
:class:`CanvasText`). It is deliberately declarative — you describe *what* to
draw, never imperative ``ctx.*`` calls — so there is no arbitrary JS, and the
runtime re-draws the ops reactively from ``State`` on every render. Op
coordinates and colours may be dynamic (``State`` / ``route`` / arithmetic)::

    Canvas(
        Rect(x=10, y=10, w=80, h=50, fill="#0a7a4f", radius=8),
        Circle(x=self.cx, y=60, r=self.r, stroke="#e23b3b", width=2),
        CanvasText("hi", x=20, y=120, fill="#1b2333", font="16px sans-serif"),
        width=300, height=160, background="#ffffff",
    )

Ops can also be spread from a comprehension — e.g. one bar per value::

    Canvas(*[Rect(x=i * 24, y=120 - v, w=18, h=v, fill="#0a7a4f")
             for i, v in enumerate(self.bars)], width=320, height=140)
"""
from __future__ import annotations

from typing import Any

from workpeg.ui.widgets.base import BaseWidget, WidgetChild


class _CanvasOp(BaseWidget):
    """Base for a canvas draw op. Valid only as a child of :class:`Canvas`."""

    def __init__(self, **fields: Any):
        super().__init__(key=fields.pop("key", None))
        self._fields = fields

    def props(self) -> dict[str, Any]:
        return {k: v for k, v in self._fields.items() if v is not None}

    def children(self) -> list[WidgetChild]:
        return []


class Rect(_CanvasOp):
    """A rectangle. ``fill`` and/or ``stroke`` are CSS colour strings; ``radius``
    rounds the corners (px)."""

    widget_type = "Rect"

    def __init__(self, *, x, y, w, h, fill=None, stroke=None,
                 width=1, radius=0, key=None):
        super().__init__(x=x, y=y, w=w, h=h, fill=fill, stroke=stroke,
                         width=width, radius=radius, key=key)


class Circle(_CanvasOp):
    """A circle of radius ``r`` centred at ``(x, y)``."""

    widget_type = "Circle"

    def __init__(self, *, x, y, r, fill=None, stroke=None, width=1, key=None):
        super().__init__(x=x, y=y, r=r, fill=fill, stroke=stroke,
                         width=width, key=key)


class Line(_CanvasOp):
    """A line segment from ``(x1, y1)`` to ``(x2, y2)``."""

    widget_type = "Line"

    def __init__(self, *, x1, y1, x2, y2, stroke="#000000", width=1, key=None):
        super().__init__(x1=x1, y1=y1, x2=x2, y2=y2, stroke=stroke,
                         width=width, key=key)


class Path(_CanvasOp):
    """A polyline / polygon through ``points`` (a list of ``[x, y]`` pairs).
    ``closed=True`` closes the shape so it can be filled; ``smooth=True`` draws a
    smooth curve through the points instead of straight segments.

    For a *compound* path — many subpaths painted as one so holes can be carved
    (a glyph or logo outline) — pass ``subpaths`` (a list of
    ``{"pts": [[x, y], …], "closed": 0|1}``) instead of ``points``, with
    ``rule="evenodd"`` or ``"nonzero"`` to choose the fill winding rule."""

    widget_type = "Path"

    def __init__(self, *, points=None, subpaths=None, rule=None, fill=None,
                 stroke=None, width=1, closed=False, smooth=False, key=None):
        super().__init__(points=points, subpaths=subpaths, rule=rule, fill=fill,
                         stroke=stroke, width=width, closed=closed,
                         smooth=smooth, key=key)


class Ellipse(_CanvasOp):
    """An ellipse centred at ``(x, y)`` with radii ``rx`` / ``ry`` (a circle is
    the ``rx == ry`` case). ``rotation`` (radians) tilts it."""

    widget_type = "Ellipse"

    def __init__(self, *, x, y, rx, ry, fill=None, stroke=None, width=1,
                 rotation=0, key=None):
        super().__init__(x=x, y=y, rx=rx, ry=ry, fill=fill, stroke=stroke,
                         width=width, rotation=rotation, key=key)


class Arc(_CanvasOp):
    """An arc of radius ``r`` centred at ``(x, y)``, from ``start`` to ``end``
    (radians). ``closed=True`` joins the ends back through the centre — a pie
    wedge you can ``fill``; otherwise it's an open arc you ``stroke``."""

    widget_type = "Arc"

    def __init__(self, *, x, y, r, start, end, fill=None, stroke=None,
                 width=1, closed=False, key=None):
        super().__init__(x=x, y=y, r=r, start=start, end=end, fill=fill,
                         stroke=stroke, width=width, closed=closed, key=key)


class CanvasImage(_CanvasOp):
    """An image drawn into the canvas at ``(x, y)`` sized ``w`` × ``h`` — distinct
    from the :class:`Image` widget (this paints onto the canvas; nothing enters
    the DOM). ``src`` is a safe URL (http(s) / relative / ``blob:`` / a
    ``data:image/`` URI); it loads asynchronously and the canvas repaints once
    it's ready."""

    widget_type = "CanvasImage"

    def __init__(self, src, *, x, y, w, h, key=None):
        super().__init__(src=src, x=x, y=y, w=w, h=h, key=key)


class CanvasText(_CanvasOp):
    """Rasterised text drawn at ``(x, y)`` — distinct from the :class:`Text`
    widget (this paints onto the canvas; nothing enters the DOM).

    ``fit_width`` (px) horizontally scales the run to span that exact width —
    useful when text was positioned with one font's metrics but is drawn in a
    substituted font (e.g. a PDF viewer), so runs abut without gaps. Only a
    modest correction is applied (a large mismatch is left at natural width)."""

    widget_type = "CanvasText"

    def __init__(self, text, *, x, y, fill="#000000",
                 font="14px sans-serif", align="left", fit_width=None, key=None):
        super().__init__(text=text, x=x, y=y, fill=fill, font=font,
                         align=align, fit_width=fit_width, key=key)


class Group(_CanvasOp):
    """Transform a set of child draw ops together: ``x`` / ``y`` translate them,
    ``rotate`` (radians) turns them, ``scale`` (a number, or ``[sx, sy]``) sizes
    them. The children are drawn under the transform, isolated from the rest."""

    widget_type = "Group"

    def __init__(self, *ops: WidgetChild, x=0, y=0, rotate=0, scale=1, key=None):
        super().__init__(x=x, y=y, rotate=rotate, scale=scale, key=key)
        self._ops = ops

    def children(self) -> list[WidgetChild]:
        return list(self._ops)


class Canvas(BaseWidget):
    """A 2D drawing surface, ``width`` × ``height`` px, painted by its draw ops.

    ``background`` (optional) fills the surface before the ops draw; the surface
    is cleared and the ops replayed on every re-render, so a canvas driven by
    ``State`` animates/updates like any other widget."""

    widget_type = "Canvas"

    def __init__(self, *ops: WidgetChild, width: int = 300, height: int = 150,
                 background: str | None = None, key: str | None = None):
        super().__init__(key=key)
        self.ops = ops
        self.width = width
        self.height = height
        self.background = background

    def children(self) -> list[WidgetChild]:
        return list(self.ops)

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {"width": self.width, "height": self.height}
        if self.background is not None:
            p["background"] = self.background
        return p
